#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define SHM_SIZE 1024
#define SHM_KEY 1234

int main() {
    int shmid;
    char *shm_addr;
    int exit_status = EXIT_SUCCESS;

    // 1. Get/Create the shared memory segment
    shmid = shmget(SHM_KEY, SHM_SIZE, IPC_CREAT | 0666);
    if (shmid == -1) {
        perror("shmget failed");
        return EXIT_FAILURE;
    }

    // 2. Attach the segment to the process's address space
    shm_addr = (char *)shmat(shmid, NULL, 0);
    if (shm_addr == (char *)-1) {
        perror("shmat failed");
        // Cleanup if attachment fails
        shmctl(shmid, IPC_RMID, NULL);
        return EXIT_FAILURE;
    }

    printf("Segment attached at address: %p\n", shm_addr);

    // 3. Use the shared memory
    strcpy(shm_addr, "Data written before detachment.");

    // 4. Detach the shared memory segment using the returned address
    if (shmdt(shm_addr) == -1) {
        perror("shmdt failed");
        exit_status = EXIT_FAILURE;
    } else {
        printf("Segment successfully detached.\n");
    }

    // 5. Clean up: Mark the segment for destruction
    // (The kernel destroys it only after all processes have detached)
    if (shmctl(shmid, IPC_RMID, NULL) == -1) {
        perror("shmctl (IPC_RMID) failed");
        exit_status = EXIT_FAILURE;
    }

    return exit_status;
}
